#!/usr/bin/env python3
"""Driver helpers for media-gallery probing."""
import os, shutil, subprocess, sys, hashlib, json, struct

BIN = '/tmp/orig/marmite_ref'
ROOT = '/tmp/probe/media-gallery/mg'
sys.path.insert(0, '/tmp/probe/media-gallery')
import importlib.util
spec = importlib.util.spec_from_file_location('mkimg', '/tmp/probe/media-gallery/mkimg.py')
mkimg = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mkimg)


def fresh(name):
    d = os.path.join(ROOT, name)
    if os.path.exists(d):
        shutil.rmtree(d)
    os.makedirs(d)
    return d


def w(path, content):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    if isinstance(content, bytes):
        open(path, 'wb').write(content)
    else:
        open(path, 'w').write(content)


def build(d, args=None, out='out', verbose='-v'):
    cmd = [BIN, '.', out]
    if verbose:
        cmd.append(verbose)
    if args:
        cmd += args
    p = subprocess.run(cmd, cwd=d, capture_output=True, text=True)
    return p


def sha(path):
    return hashlib.sha256(open(path, 'rb').read()).hexdigest()[:16]


def dims(path):
    b = open(path, 'rb').read()
    if b[:8] == b'\x89PNG\r\n\x1a\n':
        return ('png',) + struct.unpack('>II', b[16:24])
    if b[:2] == b'\xff\xd8':
        i = 2
        while i < len(b) - 1:
            if b[i] != 0xff:
                i += 1
                continue
            m = b[i+1]
            if m in (0xd8, 0xd9, 0x01) or 0xd0 <= m <= 0xd7:
                i += 2
                continue
            ln = struct.unpack('>H', b[i+2:i+4])[0]
            if 0xc0 <= m <= 0xcf and m not in (0xc4, 0xc8, 0xcc):
                h, wd = struct.unpack('>HH', b[i+5:i+9])
                ncomp = b[i+9]
                return ('jpeg', wd, h, 'ncomp=%d' % ncomp, 'sof=%02x' % m)
            i += 2 + ln
        return ('jpeg', '?', '?')
    if b[:6] in (b'GIF89a', b'GIF87a'):
        return ('gif',) + struct.unpack('<HH', b[6:10])
    if b[:4] == b'RIFF' and b[8:12] == b'WEBP':
        return ('webp', b[12:16].decode('latin1'), len(b))
    if b[:2] == b'BM':
        return ('bmp',) + struct.unpack('<ii', b[18:26])
    return ('?', b[:8].hex())


def tree(d, base=None):
    base = base or d
    r = []
    for root, dirs, files in os.walk(d):
        dirs.sort()
        for f in sorted(files):
            p = os.path.join(root, f)
            r.append((os.path.relpath(p, base), os.path.getsize(p)))
    return r


def show_tree(d, base=None, filt=None):
    for rel, size in tree(d, base):
        if filt and filt not in rel:
            continue
        print('  %-60s %8d' % (rel, size))
